const input = $('Input dari agent').first().json;
const query = String(input.query || '').trim();
const siteFilter = String(input.site || '').trim();
const topK = Math.min(Math.max(Number(input.top_k) || Number($env.RAG_TOP_K || 3), 1), 8);
const minScore = Number($env.RAG_MIN_SCORE || 0.5);
const maxChars = Number($env.RAG_MAX_CHARS_PER_PAGE || 900);
const siteName = siteFilter || $env.SITE_NAME || 'website kita';

const rows = $input.all().map((i) => i.json).filter((r) => r && r.url);
if (!rows.length) {
  return [{ json: { result: `NO_RELEVANT_INTERNAL_CONTENT\nKnowledge base untuk ${siteName} masih kosong. Pastikan website sudah di-index lewat workflow Ingestion.` } }];
}

const pages = new Map();
for (const r of rows) {
  const score = Number(r.score);
  if (!pages.has(r.url)) {
    pages.set(r.url, { url: r.url, title: r.title, outline: r.outline, word_count: r.word_count, best: score, hits: [] });
  }
  const p = pages.get(r.url);
  p.best = Math.max(p.best, score);
  const snippet = String(r.text || '').replace(/^Halaman:.*\nBagian:.*\n\n/, '').replace(/\s+/g, ' ').trim();
  p.hits.push({ score, section: r.section, snippet });
}

const ranked = [...pages.values()].sort((a, b) => b.best - a.best);
const relevant = ranked.filter((p) => p.best >= minScore).slice(0, topK);

if (!relevant.length) {
  const top = ranked[0];
  return [{ json: { result: [
    'NO_RELEVANT_INTERNAL_CONTENT',
    `Query: "${query}"${siteFilter ? ` | Website: ${siteFilter}` : ''}`,
    `Skor tertinggi: ${top.best.toFixed(3)} (${top.url}, "${top.title}") di bawah ambang ${minScore}.`,
    `Artinya ${siteName} kemungkinan BELUM punya konten untuk topik ini (peluang konten baru).`,
    'Boleh coba sekali lagi dengan query lain (sinonim, versi Inggris/Indonesia, atau subtopik yang lebih sempit).',
  ].join('\n') } }];
}

const blocks = relevant.map((p, idx) => {
  let budget = maxChars;
  const snippets = [];
  for (const h of p.hits.sort((a, b) => b.score - a.score).slice(0, 3)) {
    if (budget <= 80) break;
    const text = h.snippet.length > budget ? `${h.snippet.slice(0, budget - 1)}…` : h.snippet;
    budget -= text.length;
    snippets.push(`> [${h.section}] (skor ${h.score.toFixed(3)}) ${text}`);
  }
  return [
    `--- #${idx + 1} ---`,
    `URL: ${p.url}`,
    `Similarity: ${p.best.toFixed(3)}`,
    `Title: ${p.title}`,
    `Word count: ${p.word_count ?? '-'}`,
    'OUTLINE:',
    p.outline || '(belum ada)',
    'SNIPPETS:',
    ...snippets,
  ].join('\n');
});

return [{ json: { result: [
  '[INTERNAL_SEARCH_RESULTS]',
  `Query: "${query}"${siteFilter ? ` | Website: ${siteFilter}` : ''} | ambang relevansi ${minScore} | ${relevant.length} halaman relevan`,
  ...blocks,
  '[/INTERNAL_SEARCH_RESULTS]',
].join('\n') } }];
